import pandas as pd

def clean(df):
    df = df.drop_duplicates()
    df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
    df['island'] = df['island'].replace('Bisco', 'Biscoe')
    if df['sex'].dtype == 'object':
        df['sex'] = df['sex'].str.strip()
    return df

def answer(df):
    df = clean(df)
    result = df.groupby('species')['body_mass_g'].sum()
    return result.to_dict()
